#!/usr/bin/env bash
# Run from inside Laravel project: bash scripts/repair-site-layout.sh
# Repairs a corrupt resources/views/components/site-layout.blade.php by
# re-installing the known-good version (backup saved as *.bak).
set -euo pipefail
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
APP_ROOT="$SCRIPT_DIR"
while [ ! -f "$APP_ROOT/artisan" ] && [ "$APP_ROOT" != "/" ]; do APP_ROOT="$(dirname "$APP_ROOT")"; done
if [ ! -f "$APP_ROOT/artisan" ]; then echo "Cannot find artisan. Run from inside the Laravel project." >&2; exit 1; fi
cd "$APP_ROOT"

tmpf="$(mktemp)"
if printf '%s' "$BLOB" | base64 --decode > "$tmpf" 2>/dev/null; then
    if [ -f resources/views/components/site-layout.blade.php ]; then
        cp resources/views/components/site-layout.blade.php resources/views/components/site-layout.blade.php.repair.bak
    fi
    mv "$tmpf" resources/views/components/site-layout.blade.php
    echo "Repaired resources/views/components/site-layout.blade.php"
else
    echo "Failed to decode blob." >&2
    rm -f "$tmpf"
    exit 1
fi
php artisan view:clear >/dev/null
echo "Done. Run php artisan view:cache to verify."
